const p = $input.first().json.body || $input.first().json;
if (p.action !== 'opened') return []; // only new items
const item = p.issue || p.pull_request;
if (!item) return [];
// Optional filters - uncomment to use:
// if (!(item.labels || []).some(l => l.name === 'bug')) return [];
// if (item.user.login.endsWith('[bot]')) return [];
return [{ json: {
  kind: p.pull_request ? 'PR' : 'Issue',
  title: item.title,
  url: item.html_url,
  author: item.user.login,
  labels: (item.labels || []).map(l => l.name).join(', ') || 'none',
  preview: (item.body || '').replace(/\r?\n/g, ' ').slice(0, 140)
} }];
